Copy the workbook, aggregate `book2` columns H:J by Place, and write the matching totals into `book1` B3:B23. This produces the values that the corrected SUMPRODUCT formula would return. The script loops over all real rows rather than hardcoding the visible sample.

```python
import shutil
import math
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

v1 = vals["book1"]
v2 = vals["book2"]

def norm_key(x):
    if x is None:
        return ""
    if isinstance(x, float) and x.is_integer():
        return str(int(x))
    return str(x).strip()

def to_num(x):
    if x is None or isinstance(x, bool):
        return 0.0
    if isinstance(x, (int, float)):
        v = float(x)
    else:
        try:
            v = float(str(x).strip())
        except Exception:
            return 0.0
    return v if math.isfinite(v) else 0.0

totals = {}

for r in range(2, v2.max_row + 1):
    key = norm_key(v2.cell(row=r, column=1).value)
    if not key:
        continue
    row_sum = sum(to_num(v2.cell(row=r, column=c).value) for c in (8, 9, 10))
    totals[key] = totals.get(key, 0.0) + row_sum

ws = wb["book1"]

for r in range(3, 24):
    key = norm_key(v1.cell(row=r, column=1).value)
    val = totals.get(key, 0.0)

    if abs(val) < 1e-12:
        val = 0.0
    if isinstance(val, float) and val.is_integer():
        val = int(val)

    ws.cell(row=r, column=2).value = val
    print(r, key, val)

wb.save(OUT)
